def item_meta(code):
    """Return [{num, desc, binary}, ...] for a subdomain - used by the UI."""
    descs = ITEMS[code]
    bins = BINARY.get(code, set())
    return [{'num': i + 1, 'desc': d, 'binary': (i + 1) in bins} for i, d in enumerate(descs)]

def _validate():
    """Fail fast if any item list length disagrees with SUBDOMAINS counts."""
    import meta
    problems = []
    for code, m in meta.SUBDOMAINS.items():
        n = len(ITEMS.get(code, []))
        if n != m['items']:
            problems.append("{}: have {} items, expected {}".format(code, n, m['items']))
    if problems:
        raise AssertionError("items.py count mismatch -> " + "; ".join(problems))

_validate()
